/*
 * MS800 plugin editor for macOS (Cocoa). Draws the embedded panel art the
 * same way standalone/ui_panel.c does: the fascia, key-down and rocker
 * sprites, and the lit LED digits added on top.
 */
#import <Cocoa/Cocoa.h>

#include "ms800_gui.h"
#include "panel_layout.h"   /* generated by tools/gen_panel_art.py */

/* Panel art compiled into the binary (see cmake/embed.cmake). */
extern const unsigned char panel_bmp[], sprites_bmp[];
extern const unsigned long panel_bmp_size, sprites_bmp_size;

/* Visual grid column -> (top button, bottom button), as in ui_panel.c. */
static const struct { int top, bottom; } grid[5] = {
    { MS800_BTN_CHANNEL,    MS800_BTN_FUNCTION  },
    { MS800_BTN_PATCH,      MS800_BTN_PARAM     },
    { MS800_BTN_UP,         MS800_BTN_DOWN      },
    { MS800_BTN_UP_UP,      MS800_BTN_DOWN_DOWN },
    { MS800_BTN_NEXT_PARAM, MS800_BTN_ENTER     },
};

/* Decode an uncompressed 24-bit BMP (what gen_panel_art.py writes). */
static CGImageRef decode_bmp(const unsigned char *d, unsigned long size) {
    if (size < 54 || d[0] != 'B' || d[1] != 'M') return NULL;
    uint32_t off = d[10] | d[11] << 8 | d[12] << 16 | (uint32_t)d[13] << 24;
    int32_t  w   = (int32_t)(d[18] | d[19] << 8 | d[20] << 16 | (uint32_t)d[21] << 24);
    int32_t  h   = (int32_t)(d[22] | d[23] << 8 | d[24] << 16 | (uint32_t)d[25] << 24);
    uint16_t bpp = (uint16_t)(d[28] | d[29] << 8);
    uint32_t comp = d[30] | d[31] << 8 | d[32] << 16 | (uint32_t)d[33] << 24;
    if (bpp != 24 || comp != 0 || w <= 0 || h == 0) return NULL;
    int bottom_up = h > 0;
    if (h < 0) h = -h;
    size_t stride = ((size_t)w * 3 + 3) & ~(size_t)3;
    if (off + stride * (size_t)h > size) return NULL;

    uint8_t *rgba = malloc((size_t)w * (size_t)h * 4);
    if (!rgba) return NULL;
    for (int32_t y = 0; y < h; y++) {
        const unsigned char *src = d + off + stride * (size_t)(bottom_up ? h - 1 - y : y);
        uint8_t *dst = rgba + (size_t)y * (size_t)w * 4;
        for (int32_t x = 0; x < w; x++) {
            dst[4 * x + 0] = src[3 * x + 2];
            dst[4 * x + 1] = src[3 * x + 1];
            dst[4 * x + 2] = src[3 * x + 0];
            dst[4 * x + 3] = 255;
        }
    }
    CGColorSpaceRef cs = CGColorSpaceCreateDeviceRGB();
    CGContextRef ctx = CGBitmapContextCreate(rgba, (size_t)w, (size_t)h, 8, (size_t)w * 4, cs,
                                             kCGImageAlphaNoneSkipLast | kCGBitmapByteOrderDefault);
    CGImageRef img = ctx ? CGBitmapContextCreateImage(ctx) : NULL;
    if (ctx) CGContextRelease(ctx);
    CGColorSpaceRelease(cs);
    free(rgba);
    return img;
}

/* Class name carries the project so it can't clash with other plugins. */
@interface MS800MallumPanelView : NSView {
@public
    ms800_t    *machine;
    atomic_int *power;
    CGImageRef  panel;
    CGImageRef  sprites;
    NSTimer    *timer;
    int         held;          /* MS800_BTN_* held by the mouse, or 0 */
    uint8_t     shown_display;
    int         shown_power;
}
@end

@implementation MS800MallumPanelView

- (BOOL)isFlipped { return YES; }
- (BOOL)acceptsFirstMouse:(NSEvent *)event { (void)event; return YES; }

- (void)tick:(NSTimer *)t {
    (void)t;
    uint8_t disp = ms800_display(machine);
    int pw = atomic_load(power);
    if (disp != shown_display || pw != shown_power) [self setNeedsDisplay:YES];
}

/* Blit an atlas cell (sx in atlas px, size in logical px) at logical (x, y). */
- (void)sprite:(CGContextRef)ctx x:(int)sx w:(int)w h:(int)h at:(int)x y:(int)y {
    CGImageRef cell = CGImageCreateWithImageInRect(sprites, CGRectMake(sx, 0, w * ART_SCALE, h * ART_SCALE));
    if (!cell) return;
    /* CGContextDrawImage draws bottom-up; flip locally inside the flipped view. */
    CGContextSaveGState(ctx);
    CGContextTranslateCTM(ctx, x, y + h);
    CGContextScaleCTM(ctx, 1, -1);
    CGContextDrawImage(ctx, CGRectMake(0, 0, w, h), cell);
    CGContextRestoreGState(ctx);
    CGImageRelease(cell);
}

- (void)drawRect:(NSRect)dirty {
    (void)dirty;
    CGContextRef ctx = [[NSGraphicsContext currentContext] CGContext];
    if (!panel || !sprites) {
        CGContextSetRGBFillColor(ctx, 52 / 255.0, 55 / 255.0, 60 / 255.0, 1);
        CGContextFillRect(ctx, CGRectMake(0, 0, UI_WIN_W, UI_WIN_H));
        return;
    }
    CGContextSetInterpolationQuality(ctx, kCGInterpolationHigh);
    CGContextSaveGState(ctx);
    CGContextTranslateCTM(ctx, 0, UI_WIN_H);
    CGContextScaleCTM(ctx, 1, -1);
    CGContextDrawImage(ctx, CGRectMake(0, 0, UI_WIN_W, UI_WIN_H), panel);
    CGContextRestoreGState(ctx);

    int pw = atomic_load(power);
    [self sprite:ctx x:(pw ? SPR_ROCKER_ON_X : SPR_ROCKER_OFF_X) w:SWITCH_W h:SWITCH_H at:SWITCH_X y:SWITCH_Y];

    for (int i = 0; i < 5; i++) {
        int bx = BTN_X0 + i * BTN_PITCH;
        if (ms800_button(machine, grid[i].top))    [self sprite:ctx x:SPR_KEYDOWN_X w:BTN_W h:BTN_H at:bx y:ROW1_Y];
        if (ms800_button(machine, grid[i].bottom)) [self sprite:ctx x:SPR_KEYDOWN_X w:BTN_W h:BTN_H at:bx y:ROW2_Y];
    }

    uint8_t disp = ms800_display(machine);
    if (pw) {
        /* Lit digits are black-backed with glow: add them over the red filter. */
        int step = DIG_SPR_W * ART_SCALE;
        CGContextSetBlendMode(ctx, kCGBlendModePlusLighter);
        [self sprite:ctx x:SPR_DIGIT0_X + ((disp >> 4) & 0xF) * step w:DIG_SPR_W h:DIG_SPR_H at:DIG1_X y:DIG_Y];
        [self sprite:ctx x:SPR_DIGIT0_X + (disp & 0xF) * step        w:DIG_SPR_W h:DIG_SPR_H at:DIG2_X y:DIG_Y];
        CGContextSetBlendMode(ctx, kCGBlendModeNormal);
    }
    shown_display = disp;
    shown_power = pw;
}

static int hit_button(NSPoint p) {
    for (int i = 0; i < 5; i++) {
        int bx = BTN_X0 + i * BTN_PITCH;
        if (p.x >= bx && p.x < bx + BTN_W) {
            if (p.y >= ROW1_Y && p.y < ROW1_Y + BTN_H) return grid[i].top;
            if (p.y >= ROW2_Y && p.y < ROW2_Y + BTN_H) return grid[i].bottom;
        }
    }
    return 0;
}

- (void)mouseDown:(NSEvent *)event {
    NSPoint p = [self convertPoint:[event locationInWindow] fromView:nil];
    if (p.x >= SWITCH_X && p.x < SWITCH_X + SWITCH_W && p.y >= SWITCH_Y && p.y < SWITCH_Y + SWITCH_H) {
        atomic_store(power, !atomic_load(power));
        [self setNeedsDisplay:YES];
        return;
    }
    held = hit_button(p);
    if (held) {
        ms800_set_button(machine, held, 1);
        [self setNeedsDisplay:YES];
    }
}

- (void)mouseUp:(NSEvent *)event {
    (void)event;
    if (held) {
        ms800_set_button(machine, held, 0);
        held = 0;
        [self setNeedsDisplay:YES];
    }
}

@end

struct ms800_gui {
    void *view;   /* MS800MallumPanelView, retained */
};

void ms800_gui_size(unsigned *width, unsigned *height) {
    *width = UI_WIN_W;
    *height = UI_WIN_H;
}

ms800_gui *ms800_gui_create(ms800_t *m, atomic_int *power) {
    ms800_gui *gui = calloc(1, sizeof(*gui));
    if (!gui) return NULL;
    MS800MallumPanelView *v = [[MS800MallumPanelView alloc] initWithFrame:NSMakeRect(0, 0, UI_WIN_W, UI_WIN_H)];
    v->machine = m;
    v->power = power;
    v->panel = decode_bmp(panel_bmp, panel_bmp_size);
    v->sprites = decode_bmp(sprites_bmp, sprites_bmp_size);
    v->shown_display = 0xFF;
    v->timer = [NSTimer timerWithTimeInterval:1.0 / 30.0 target:v selector:@selector(tick:) userInfo:nil repeats:YES];
    [[NSRunLoop mainRunLoop] addTimer:v->timer forMode:NSRunLoopCommonModes];
    gui->view = (__bridge_retained void *)v;
    return gui;
}

void ms800_gui_destroy(ms800_gui *gui) {
    if (!gui) return;
    MS800MallumPanelView *v = (__bridge_transfer MS800MallumPanelView *)gui->view;
    if (v->held) ms800_set_button(v->machine, v->held, 0);
    [v->timer invalidate];
    v->timer = nil;   /* the timer retains the view; break the cycle */
    [v removeFromSuperview];
    if (v->panel) CGImageRelease(v->panel);
    if (v->sprites) CGImageRelease(v->sprites);
    v->panel = v->sprites = NULL;
    free(gui);
}

bool ms800_gui_set_parent(ms800_gui *gui, void *native_parent) {
    NSView *parent = (__bridge NSView *)native_parent;
    MS800MallumPanelView *v = (__bridge MS800MallumPanelView *)gui->view;
    if (!parent) return false;
    [parent addSubview:v];
    return true;
}

void ms800_gui_show(ms800_gui *gui, bool visible) {
    MS800MallumPanelView *v = (__bridge MS800MallumPanelView *)gui->view;
    [v setHidden:!visible];
}
